void Line3DClass::Set_Opacity(float opacity)
{
	if (opacity < 1.0f)
	{
		Shader = ShaderClass::_PresetAlphaSolidShader;
		Set_Sort_Level(1);
	}
	else
	{
		Shader = ShaderClass::_PresetOpaqueSolidShader;
		Set_Sort_Level(0);
	}
	Color.W = opacity;
}

// FUNCTION: BFME2 0x001673D0 size=621 name=??0Line3DClass@@QAE@ABVVector3@@0MMMMM@Z evidence=N:ledger
Line3DClass::Line3DClass(const Vector3 &start, const Vector3 &end, float width, float r, float g, float b, float opacity)
{
	Length = (end - start).Length();
	Width = width;

	// Create box model with origin at start point (X is major axis).
	float halfw = Width * 0.5f;

	vert[0].X = 0.0f;
	vert[0].Y = -halfw;
	vert[0].Z = -halfw;
	vert[1].X = 0.0f;
	vert[1].Y = halfw;
	vert[1].Z = -halfw;
	vert[2].X = 0.0f;
	vert[2].Y = -halfw;
	vert[2].Z = halfw;
	vert[3].X = 0.0f;
	vert[3].Y = halfw;
	vert[3].Z = halfw;
	vert[4].X = Length;
	vert[4].Y = -halfw;
	vert[4].Z = -halfw;
	vert[5].X = Length;
	vert[5].Y = halfw;
	vert[5].Z = -halfw;
	vert[6].X = Length;
	vert[6].Y = -halfw;
	vert[6].Z = halfw;
	vert[7].X = Length;
	vert[7].Y = halfw;
	vert[7].Z = halfw;

	Color.X = r;
	Color.Y = g;
	Color.Z = b;
	Set_Opacity(opacity);

	// Set box transform so that the origin is at the start point and it 'looks towards' the endpoint.
	Matrix3D transform(true);
	transform.Obj_Look_At(start, end, 0.0);
	Set_Transform(transform);
}

